#!/usr/bin/env bash
# Builds the project site into target/site: the front page and its assets
# from site/, and the docs (mdBook, book.toml) under docs/. The terminal
# screens in site/index.html are generated by a test
# (crates/irsty-tui/tests/site.rs); `mise run site` regenerates them first.
set -euo pipefail

cd "$(dirname "$0")/.."
out=target/site
rm -rf "$out"
mdbook build
# docs.css and docs.js belong to the book (book.toml), not the front page.
find site -type f ! -name 'docs.*' | while read -r file; do
  mkdir -p "$out/$(dirname "${file#site/}")"
  cp "$file" "$out/${file#site/}"
done
touch "$out/.nojekyll"
echo "Built $out"
